def solve(y_true,y_pred):
    labels=set(y_true); recalls=[]
    for c in labels:
      ids=[i for i,y in enumerate(y_true) if y==c]
      recalls.append(sum(y_pred[i]==c for i in ids)/len(ids))
    return sum(recalls)/len(recalls) if recalls else 0.0

def solve(ranking,relevant):
    relevant=set(relevant)
    if not relevant:return 0.0
    hits=0; total=0.0
    for i,item in enumerate(ranking,1):
      if item in relevant:
       hits+=1; total+=hits/i
    return total/len(relevant)

